1	// Both callers require Retry-After seconds/date parsing, 3600-second ceiling and caller fallback.
2	export function retrySeconds(value: string | null, now: number, fallback = 5): number {
3	  if (value == null || value.trim() === '') return fallback;
4	  const normalized = value.trim();
5	  if (/^\d+$/.test(normalized)) {
6	    const seconds = Number(normalized);
7	    if (!Number.isSafeInteger(seconds)) return fallback;
8	    return Math.min(seconds, 3600);
9	  }
10	  const deadline = Date.parse(normalized);
11	  if (!Number.isFinite(deadline)) return fallback;
12	  const remaining = Math.ceil((deadline - now) / 1000);
13	  if (remaining < 0) return 0;
14	  return Math.min(remaining, 3600);
15	}
